package domain

import "context"

// ImportInput is the input for the initial import of a workspace from GitHub.
type ImportInput struct {
	RepoURL       string
	DefaultBranch string
	Token         string // optional; falls back to GITHUB_TOKEN env var
}

// GitHubWorkspaceAdapter fetches and parses a GitHub management repository.
// It never reads from or writes to the database.
type GitHubWorkspaceAdapter interface {
	// ImportWorkspace performs a full reconciliation fetch of the given repository.
	// Returns a complete WorkspaceSnapshot or an error if the repo is inaccessible.
	ImportWorkspace(ctx context.Context, input ImportInput) (*WorkspaceSnapshot, error)

	// SyncWorkspace re-fetches the repository at the given ref (branch or SHA)
	// and returns an updated WorkspaceSnapshot.
	SyncWorkspace(ctx context.Context, workspaceID, repoURL, ref string) (*WorkspaceSnapshot, error)
}

// DbWorkspaceAdapter reads and writes workspace data in PostgreSQL.
// It never calls GitHub.
type DbWorkspaceAdapter interface {
	// ListWorkspaces returns summary rows for all saved workspaces.
	ListWorkspaces(ctx context.Context) ([]WorkspaceSummary, error)

	// GetWorkspace returns the full workspace detail for the given workspace ID.
	GetWorkspace(ctx context.Context, workspaceID string) (*WorkspaceDetail, error)

	// GetFeature returns the full feature detail for the given workspace and feature IDs.
	GetFeature(ctx context.Context, workspaceID, featureID string) (*FeatureDetail, error)

	// GetTask returns the full task detail for the given workspace and task IDs.
	GetTask(ctx context.Context, workspaceID, taskID string) (*TaskDetail, error)

	// ListFeatureTasks returns task summaries for all tasks in the given feature.
	ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]TaskSummary, error)

	// ListActivity returns activity events filtered by the given scope.
	ListActivity(ctx context.Context, workspaceID string, scope ActivityScope) ([]ActivityEvent, error)

	// SaveSnapshot upserts all core tables from the given snapshot inside a single transaction.
	SaveSnapshot(ctx context.Context, workspaceID string, snapshot *WorkspaceSnapshot) error

	// GetActiveSnapshot returns the latest WorkspaceSnapshot for the given workspace.
	// Returns nil, nil when no snapshot has been saved yet.
	GetActiveSnapshot(ctx context.Context, workspaceID string) (*WorkspaceSnapshot, error)

	// GetLatestSyncRun returns the most recent sync run record for staleness derivation.
	// Returns nil, nil when no sync has been recorded.
	GetLatestSyncRun(ctx context.Context, workspaceID string) (*SyncRun, error)
}

package domain

import "time"

// SourceState describes the freshness and error state of a workspace's data.
type SourceState struct {
	Stale        bool       `json:"stale"`
	LastSyncedAt *time.Time `json:"last_synced_at,omitempty"`
	ErrorCode    string     `json:"error_code,omitempty"`
	ErrorMessage string     `json:"error_message,omitempty"`
}

// PullRequestRef is a reference to a pull request associated with a task.
type PullRequestRef struct {
	Label  string `json:"label"`
	URL    string `json:"url"`
	Status string `json:"status"`
	Repo   string `json:"repo"`
}

// ActivityEvent is a single normalized activity record from feature history or task logs.
type ActivityEvent struct {
	Action     string    `json:"action"`
	Scope      string    `json:"scope"`
	Actor      string    `json:"actor"`
	OccurredAt time.Time `json:"occurred_at"`
	Note       string    `json:"note,omitempty"`
	FeatureID  string    `json:"feature_id,omitempty"`
	TaskID     string    `json:"task_id,omitempty"`
}

// ActivityScope filters activity queries by scope.
type ActivityScope struct {
	FeatureID string
	TaskID    string
}

// WorkspaceSummary is the list-view representation of a workspace.
type WorkspaceSummary struct {
	ID          string      `json:"id"`
	Name        string      `json:"name"`
	Slug        string      `json:"slug"`
	RepoURL     string      `json:"repo_url"`
	SourceState SourceState `json:"source_state"`
	UpdatedAt   time.Time   `json:"updated_at"`
}

// WorkspaceDetail is the full workspace view including features and tasks.
type WorkspaceDetail struct {
	WorkspaceSummary
	Features []FeatureSummary `json:"features"`
	Tasks    []TaskSummary    `json:"tasks"`
}

// FeatureSummary is the list-view representation of a feature.
type FeatureSummary struct {
	FeatureID    string     `json:"feature_id"`
	Title        string     `json:"title"`
	Status       string     `json:"status"`
	CurrentStage string     `json:"current_stage,omitempty"`
	UpdatedAt    time.Time  `json:"updated_at"`
	TaskCounts   TaskCounts `json:"task_counts"`
}

// TaskCounts summarises task status distribution within a feature.
type TaskCounts struct {
	Total      int `json:"total"`
	Done       int `json:"done"`
	InProgress int `json:"in_progress"`
	Blocked    int `json:"blocked"`
	Ready      int `json:"ready"`
	Todo       int `json:"todo"`
}

// DocumentLink is a GitHub web URL for a feature document.
type DocumentLink struct {
	DocumentType string `json:"document_type"`
	SourcePath   string `json:"source_path"`
	URL          string `json:"url"`
}

// FeatureDetail is the full feature view including documents, tasks, and activity.
type FeatureDetail struct {
	FeatureSummary
	WorkspaceID string          `json:"workspace_id"`
	Documents   []DocumentLink  `json:"documents"`
	Tasks       []TaskSummary   `json:"tasks"`
	Activity    []ActivityEvent `json:"activity"`
	SourceState SourceState     `json:"source_state"`
}

// TaskSummary is the list-view representation of a task.
type TaskSummary struct {
	TaskID        string `json:"task_id"`
	FeatureID     string `json:"feature_id"`
	Title         string `json:"title"`
	Status        string `json:"status"`
	Repo          string `json:"repo,omitempty"`
	Branch        string `json:"branch,omitempty"`
	NextAction    string `json:"next_action,omitempty"`
	IsBlocked     bool   `json:"is_blocked"`
	BlockedReason string `json:"blocked_reason,omitempty"`
}

// ExecutionContext holds execution metadata for a task.
type ExecutionContext struct {
	ActorType     string `json:"actor_type"`
	LastUpdatedBy string `json:"last_updated_by,omitempty"`
	LastUpdatedAt string `json:"last_updated_at,omitempty"`
}

// TaskDetail is the full task view including dependencies, PR refs, and activity.
type TaskDetail struct {
	TaskSummary
	WorkspaceID    string           `json:"workspace_id"`
	DependsOn      []string         `json:"depends_on"`
	Execution      ExecutionContext `json:"execution"`
	PRRefs         []PullRequestRef `json:"pr_refs,omitempty"`
	BlockedContext *BlockedContext  `json:"blocked_context,omitempty"`
	Activity       []ActivityEvent  `json:"activity"`
}

// BlockedContext holds context about why a task is blocked and how to resume.
type BlockedContext struct {
	WIPBranch  string `json:"wip_branch,omitempty"`
	WIPSha     string `json:"wip_sha,omitempty"`
	PushedAt   string `json:"pushed_at,omitempty"`
	Suggestion string `json:"suggestion,omitempty"`
}

// WorkspaceSnapshot is the parsed in-memory representation of a GitHub workspace
// returned by GitHubWorkspaceAdapter. It is the input to the DB persistence layer.
type WorkspaceSnapshot struct {
	WorkspaceID  string
	Name         string
	Slug         string
	RepoURL      string
	CommitSHA    string
	FetchedAt    time.Time
	Features     []FeatureSnapshot
	Repos        []RepoEntry
	SourceErrors []SourceError
}

// RepoEntry maps to workspace.yaml repos[].
type RepoEntry struct {
	RepoID     string `json:"repo_id"`
	BaseBranch string `json:"base_branch,omitempty"`
}

// FeatureSnapshot is the parsed representation of a single feature directory.
type FeatureSnapshot struct {
	FeatureID    string
	Title        string
	Status       string
	CurrentStage string
	NextAction   string
	SourcePath   string
	SourceHash   string
	Documents    []DocumentSnapshot
	Tasks        []TaskSnapshot
	Activity     []ActivityEvent
}

// DocumentSnapshot is the parsed representation of a feature document.
type DocumentSnapshot struct {
	DocumentType string
	SourcePath   string
	URL          string
}

// TaskSnapshot is the parsed representation of a task YAML file.
type TaskSnapshot struct {
	TaskID        string
	FeatureID     string
	Title         string
	Status        string
	Repo          string
	Branch        string
	DependsOn     []string
	BlockedReason string
	Execution     map[string]interface{}
	PR            map[string]interface{}
	WorkspacePR   map[string]interface{}
	SourcePath    string
	SourceHash    string
	Activity      []ActivityEvent
}

package domain

import "fmt"

// ErrorSource identifies the system that produced a SourceError.
type ErrorSource string

const (
	ErrorSourceGitHub     ErrorSource = "github"
	ErrorSourceDatabase   ErrorSource = "database"
	ErrorSourceParser     ErrorSource = "parser"
	ErrorSourceAdapter    ErrorSource = "adapter"
	ErrorSourceValidation ErrorSource = "validation"
)

// ErrorCode is a machine-readable error identifier.
type ErrorCode string

const (
	// GitHub errors.
	ErrGitHubRateLimit    ErrorCode = "GITHUB_RATE_LIMIT"
	ErrGitHubNotFound     ErrorCode = "GITHUB_NOT_FOUND"
	ErrGitHubUnauthorized ErrorCode = "GITHUB_UNAUTHORIZED"
	ErrGitHubNetworkError ErrorCode = "GITHUB_NETWORK_ERROR"
	ErrGitHubServerError  ErrorCode = "GITHUB_SERVER_ERROR"

	// Parser errors.
	ErrParserInvalidYAML  ErrorCode = "PARSER_INVALID_YAML"
	ErrParserMissingField ErrorCode = "PARSER_MISSING_FIELD"
	ErrParserUnexpected   ErrorCode = "PARSER_UNEXPECTED"

	// Database errors.
	ErrDatabaseConnection  ErrorCode = "DATABASE_CONNECTION"
	ErrDatabaseQuery       ErrorCode = "DATABASE_QUERY"
	ErrDatabaseTransaction ErrorCode = "DATABASE_TRANSACTION"
	ErrDatabaseNotFound    ErrorCode = "DATABASE_NOT_FOUND"

	// Adapter errors.
	ErrAdapterInternal ErrorCode = "ADAPTER_INTERNAL"
	ErrAdapterTimeout  ErrorCode = "ADAPTER_TIMEOUT"

	// Validation errors.
	ErrValidationInvalidURL   ErrorCode = "VALIDATION_INVALID_URL"
	ErrValidationMissingInput ErrorCode = "VALIDATION_MISSING_INPUT"
)

// SourceError is the normalized error shape for all backend errors.
// It carries a machine-readable code, a user-facing message, the error source,
// a retryability hint, and an optional path for file-level errors.
type SourceError struct {
	Code      ErrorCode   `json:"code"`
	Message   string      `json:"message"`
	Source    ErrorSource `json:"source"`
	Retryable bool        `json:"retryable"`
	Path      string      `json:"path,omitempty"`
}

func (e SourceError) Error() string {
	if e.Path != "" {
		return fmt.Sprintf("[%s/%s] %s (path: %s)", e.Source, e.Code, e.Message, e.Path)
	}
	return fmt.Sprintf("[%s/%s] %s", e.Source, e.Code, e.Message)
}

// NewGitHubRateLimitError returns a SourceError for GitHub rate limit responses.
func NewGitHubRateLimitError(retryAfterMsg string) SourceError {
	msg := "GitHub API rate limit reached."
	if retryAfterMsg != "" {
		msg += " " + retryAfterMsg
	}
	return SourceError{
		Code:      ErrGitHubRateLimit,
		Message:   msg,
		Source:    ErrorSourceGitHub,
		Retryable: true,
	}
}

// NewGitHubNotFoundError returns a SourceError for inaccessible or missing repos.
func NewGitHubNotFoundError(repoURL string) SourceError {
	return SourceError{
		Code:      ErrGitHubNotFound,
		Message:   fmt.Sprintf("Repository not found or inaccessible: %s", repoURL),
		Source:    ErrorSourceGitHub,
		Retryable: false,
	}
}

// NewGitHubNetworkError returns a SourceError for transient network failures.
func NewGitHubNetworkError(detail string) SourceError {
	return SourceError{
		Code:      ErrGitHubNetworkError,
		Message:   fmt.Sprintf("GitHub API request failed: %s", detail),
		Source:    ErrorSourceGitHub,
		Retryable: true,
	}
}

// NewParserInvalidYAMLError returns a SourceError for YAML parse failures.
func NewParserInvalidYAMLError(path, detail string) SourceError {
	return SourceError{
		Code:      ErrParserInvalidYAML,
		Message:   fmt.Sprintf("Invalid YAML in %s: %s", path, detail),
		Source:    ErrorSourceParser,
		Retryable: false,
		Path:      path,
	}
}

// NewValidationError returns a SourceError for input validation failures.
func NewValidationError(code ErrorCode, message string) SourceError {
	return SourceError{
		Code:      code,
		Message:   message,
		Source:    ErrorSourceValidation,
		Retryable: false,
	}
}

// NewDatabaseError returns a SourceError for database failures.
func NewDatabaseError(code ErrorCode, detail string) SourceError {
	return SourceError{
		Code:      code,
		Message:   fmt.Sprintf("Database error: %s", detail),
		Source:    ErrorSourceDatabase,
		Retryable: true,
	}
}

// APIError is the HTTP response body for error responses.
type APIError struct {
	Code       ErrorCode   `json:"code"`
	Message    string      `json:"message"`
	Source     ErrorSource `json:"source"`
	Retryable  bool        `json:"retryable"`
	CachedData interface{} `json:"cached_data,omitempty"`
}

// FromSourceError converts a SourceError to an APIError.
func FromSourceError(e SourceError, cachedData interface{}) APIError {
	return APIError{
		Code:       e.Code,
		Message:    e.Message,
		Source:     e.Source,
		Retryable:  e.Retryable,
		CachedData: cachedData,
	}
}

