			_, _ = w.Write([]byte(contentJSON(wsData)))
		case strings.Contains(path, "/contents/docs/features/bad-feature/status.yaml"):
			w.WriteHeader(200)
			_, _ = w.Write([]byte(contentJSON(invalidYAML)))
